const modelosPadrao = [
    "gemini-2.5-flash-lite",
    "gemini-2.0-flash-exp",
    "gemini-exp-1206",
    "gemini-2.5-pro"
];

function criarConfigPadrao() {
    return {
        chaves: chavesConfigPadrao,
        modelos: modelosPadrao,
        config: {
            modo_rotacao: "sequencial",
            rotacionar_modelos: false,
            chamadas_por_chave: 1
        }
    };
}

function carregarConfig() {
    const CONFIG_PATH = getConfigPath();
    try {
        if (fs.existsSync(CONFIG_PATH)) {
            const config = JSON.parse(fs.readFileSync(CONFIG_PATH, 'utf8'));
            if (!config.chaves || config.chaves.length === 0) config.chaves = chavesConfigPadrao;
            if (!config.modelos) config.modelos = modelosPadrao;
            if (!config.config) config.config = criarConfigPadrao().config;
            return config;
        }
    } catch (err) {}
    const config = criarConfigPadrao();
    salvarConfig(config);
    return config;
}

function salvarConfig(config) {
    const CONFIG_PATH = getConfigPath();
    try {
        const dir = path.dirname(CONFIG_PATH);
        if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
        fs.writeFileSync(CONFIG_PATH, JSON.stringify(config, null, 2), 'utf8');
    } catch (err) {}
}

const configExterno = carregarConfig();
const chavesConfig = configExterno.chaves;
const modelos = configExterno.modelos;
const cfg = configExterno.config || {};

const MODO_ROTACAO = cfg.modo_rotacao || "sequencial";
const ROTACIONAR_MODELOS = cfg.rotacionar_modelos || false;
const CHAMADAS_POR_CHAVE = cfg.chamadas_por_chave || 1;

const memoria = $getWorkflowStaticData('global');

if (!memoria.rotador) {
    memoria.rotador = {
        chaveIndex: 0,
        modeloIndex: 0,
        contadorChamadas: 0,
        totalChamadas: 0,
        ultimaAtualizacao: Date.now()
    };
}

let estado = memoria.rotador;

function proximaChaveSequencial() {
    estado.chaveIndex = (estado.chaveIndex + 1) % chavesConfig.length;
    return chavesConfig[estado.chaveIndex];
}

function proximaChaveRandom() {
    estado.chaveIndex = Math.floor(Math.random() * chavesConfig.length);
    return chavesConfig[estado.chaveIndex];
}

function proximaChaveBalanceada() {
    estado.contadorChamadas++;
    if (estado.contadorChamadas >= CHAMADAS_POR_CHAVE) {
        estado.contadorChamadas = 0;
        estado.chaveIndex = (estado.chaveIndex + 1) % chavesConfig.length;
    }
    return chavesConfig[estado.chaveIndex];
}

function selecionarChave() {
    switch (MODO_ROTACAO) {
        case "random": return proximaChaveRandom();
        case "balanceado": return proximaChaveBalanceada();
        case "sequencial":
        default: return proximaChaveSequencial();
    }
}

function selecionarModelo() {
    if (ROTACIONAR_MODELOS && estado.chaveIndex === 0) {
        estado.modeloIndex = (estado.modeloIndex + 1) % modelos.length;
    }
    return modelos[estado.modeloIndex];
}

// ==========================================================
// GERAR 10 CHAVES DIFERENTES EMBARALHADAS
// ==========================================================
function shuffleArray(array) {
    const arr = [...array];
    for (let i = arr.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [arr[i], arr[j]] = [arr[j], arr[i]];
    }
    return arr;
}

// Embaralha todas as chaves
const chavesEmbaralhadas = shuffleArray(chavesConfig);

// Pool embaralhado
const poolEmbaralhado = chavesEmbaralhadas.map(c => c.key);

// Modelos embaralhados também
const modelosEmbaralhados = shuffleArray(modelos);

// Pega 10 chaves diferentes
const chavesDiferentes = {};
const maxChaves = Math.min(10, chavesEmbaralhadas.length);
for (let i = 0; i < maxChaves; i++) {
    chavesDiferentes[`key${i + 1}`] = chavesEmbaralhadas[i].key;
}

// Pega 10 modelos random
const modelosRandom = {};
for (let i = 0; i < 10; i++) {
    const idx = Math.floor(Math.random() * modelos.length);
    modelosRandom[`model${i + 1}`] = modelos[idx];
}

const chaveSelecionada = selecionarChave();
const modeloSelecionado = selecionarModelo();

estado.totalChamadas++;
estado.ultimaAtualizacao = Date.now();
memoria.rotador = estado;

// ==========================================================
// OUTPUT
// ==========================================================
return [
    {
        json: {
            // CAMPO FIXO (sequencial - rotaciona a cada execução)
            apiKey: chaveSelecionada.key,
            modelName: modeloSelecionado,

            // =====================================================
            // POOL EMBARALHADO - use índices fixos, chaves mudam!
            // =====================================================
            pool: poolEmbaralhado,

            // =====================================================
            // MODELOS EMBARALHADOS
            // =====================================================
            modelos: modelosEmbaralhados,

            // Atalhos key1-key10 e model1-model10
            ...chavesDiferentes,
            ...modelosRandom,

            // DEBUG
            debug: {
                chaveNome: chaveSelecionada.nome,
                chaveIndex: estado.chaveIndex,
                totalChaves: chavesConfig.length,
                modeloIndex: estado.modeloIndex,
                totalModelos: modelos.length,
                modoRotacao: MODO_ROTACAO,
                totalChamadas: estado.totalChamadas,
                configPath: getConfigPath()
            }
        }
    }
];

// O 'items' é um array de itens de entrada em um nó "Function".
const outputItems = [];

for (const item of items) {
  // ATENÇÃO: Agora acessando 'item.json.output'
  const fullMessage = $('multi atendentes').first().json.output;

  if (fullMessage) {
    // Divide a mensagem em partes usando '\n\n' como delimitador.
    const parts = fullMessage.split('\n\n');

    // Para cada parte, cria um novo item para a saída.
    // Isso fará com que cada pedaço da mensagem se torne um item separado no fluxo.
    parts.forEach(part => {
      outputItems.push({
        json: {
          partOfMessage: part.trim() // .trim() remove espaços em branco extras
        }
      });
    });
  } else {
    // Se a propriedade 'output' não existir ou for vazia,
    // retorne o item original para não perder dados, ou ajuste conforme sua necessidade.
    outputItems.push(item);
  }
}

// Retorna o array de novos itens, onde cada item é uma parte da mensagem.
return outputItems;

const MAX_LENGTH = 200; // Tamanho máximo de caracteres por parte

// Função para dividir a conversa em partes menores
function splitConversation(conversation, maxLength) {
  const paragraphs = conversation.split(/\n+/).map(p => p.trim()).filter(p => p);
  let currentPart = "";
  const conversationParts = [];

  for (const paragraph of paragraphs) {
    if ((currentPart.length + paragraph.length + 2) > maxLength) {
      conversationParts.push(currentPart.trim());
      currentPart = "";
    }
    currentPart += (currentPart ? "\n\n" : "") + paragraph;
  }

  if (currentPart) {
    conversationParts.push(currentPart.trim());
  }

  return conversationParts;
}

// Função para formatar links em Markdown (exemplo)
function formatLinks(message) {
  return message.replace(/(https?:\/\/[^\s]+)/g, `<a href="$1">$1</a>`);
}

// Função para verificar se uma mensagem contém uma pergunta
function containsQuestion(message) {
  return /\?/.test(message);
}

// Função para remover mensagens duplicadas
function removeDuplicateMessages(conversa) {
  const uniqueMessages = [];
  conversa.forEach(msg => {
    if (!uniqueMessages.some(existingMsg => existingMsg.mensagem === msg.mensagem)) {
      uniqueMessages.push(msg);
    }
  });
  return uniqueMessages;
}

// Função principal para processar as conversas
function processConversations(items) {
  const aggregatedConversation = { comversa: [] };

  // Iterar sobre as mensagens recebidas
  for (const item of items) {
    let conversation = item.json.conversation || "";
    let pushName = item.json.pushName?.trim() || "Agente"; // Garantir valor padrão

    // Dividir a conversa em partes menores
    const conversationParts = splitConversation(conversation, MAX_LENGTH);

    // Adicionar as partes da conversa ao histórico consolidado
    for (const part of conversationParts) {
      let formattedMessage = formatLinks(part); // Formatar links
      aggregatedConversation.comversa.push({
        remetente: pushName,
        mensagem: formattedMessage
      });
    }
  }

  // Remover mensagens duplicadas
  aggregatedConversation.comversa = removeDuplicateMessages(aggregatedConversation.comversa);

  // Adicionar logs para depuração
  console.log(`Processando ${aggregatedConversation.comversa.length} mensagens`);

  return [{ json: aggregatedConversation }];
}

// Processar as mensagens de entrada
return processConversations(items);

