/**
 * ============================================================================
 * SCRIPT DE SAÍDA UNIVERSAL B2B (PROXY FRONT-END MULTIMODAL + INSIGHTS)
 * ============================================================================
 * Objetivo: Atuar como a ponte definitiva entre o ecossistema do n8n e a
 * interface (Front-End) Inovare B2B. Este pipeline de alta engenharia executa
 * múltiplas tarefas primárias:
 * 1. BUSCA HEURÍSTICA DE TEXTO: Varredura profunda para garantir a captura.
 * 2. VARREDURA DINÂMICA DE INSIGHTS: Extração limpa dos dados da secretária.
 * 3. PROCESSAMENTO BINÁRIO: Conversão serializada de arquivos para Base64.
 * 4. EXCLUSÃO MÚTUA DE ÁUDIO/TEXTO: Se um áudio for gerado, o texto é 
 * explicitamente suprimido para garantir a renderização de uma nota de voz pura.
 */

// ============================================================================
// FUNÇÕES AUXILIARES DE ALTA PERFORMANCE (HELPERS)
// ============================================================================

/**
 * Validação rigorosa de tipos para evitar quebra de memória no V8 Engine.
 * @param {any} value - Valor a ser testado.
 * @param {string} expectedType - Tipo esperado (ex: 'string', 'object').
 * @returns {boolean} Verdadeiro se o tipo coincidir e não for nulo.
 */
const isTypeStrict = (value, expectedType) => {
    if (value === null || value === undefined) return false;
    if (expectedType === 'array') return Array.isArray(value);
    if (expectedType === 'object') return typeof value === 'object' && !Array.isArray(value);
    return typeof value === expectedType;
};

/**
 * Sanitiza strings e remove quebras de linha defeituosas ou artefatos que 
 * possam corromper a renderização do DOM no HTML.
 * @param {any} input - Texto bruto.
 * @returns {string} String limpa e pronta para produção.
 */
const sanitizeText = (input) => {
    if (!input) return "";
    if (isTypeStrict(input, 'object') || isTypeStrict(input, 'array')) {
        try {
            return JSON.stringify(input);
        } catch (e) {
            return "Erro ao processar artefato textual de saída.";
        }
    }
    return String(input).trim();
};

/**
 * Formata chaves no padrão snake_case para Title Case Legível.
 * Exemplo: "etapa_atendimento" -> "Etapa Atendimento"
 * @param {string} key - A chave bruta do JSON.
 * @returns {string} A chave formatada e amigável para UI.
 */
const formatFriendlyKeyName = (key) => {
    if (!key) return "";
    return key
        .split('_')
        .map(word => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
        .join(' ');
};

/**
 * Motor de Varredura Profunda para Objetos JSON da Secretária.
 * Itera sobre o objeto, descarta valores nulos/vazios e monta uma string Markdown.
 * @param {object} dadosSecretaria - Objeto JSON retornado pelo nó.
 * @returns {object|null} Objeto contendo notas formatadas e status, ou nulo se vazio.
 */
const extrairInsightsSecretaria = (dadosSecretaria) => {
    if (!dadosSecretaria || !isTypeStrict(dadosSecretaria, 'object')) {
        return null;
    }

    let notasConstruidas = "";
    let temperaturaIdentificada = "Analisando Lead...";
    const chaves = Object.keys(dadosSecretaria);

    for (let j = 0; j < chaves.length; j++) {
        const chaveOriginal = chaves[j];
        const valor = dadosSecretaria[chaveOriginal];

        // Regra de Negócio Crítica: Excluir tudo que for null, undefined ou string vazia
        if (valor !== null && valor !== undefined && valor !== "") {

            // Tratamento especial para capturar o status térmico como badge principal
            if (chaveOriginal === 'sentimento_conversa' || chaveOriginal === 'nivel_interesse_compra' || chaveOriginal === 'etapa_atendimento') {
                temperaturaIdentificada = valor; 
            }

            // Sanitiza e anexa ao bloco formatado
            const chaveAmigavel = formatFriendlyKeyName(chaveOriginal);
            notasConstruidas += `🔹 **${chaveAmigavel}:** ${sanitizeText(valor)}\n`;
        }
    }

    if (notasConstruidas.trim().length === 0) {
        return null;
    }

    return {
        notas: notasConstruidas.trim(),
        status_lead: sanitizeText(temperaturaIdentificada)
    };
};

/**
 * Motor Heurístico de Busca Global de Textos.
 * Varre o escopo local e retrocede para nós adjacentes conhecidos para garantir
 * que a resposta gerada pelo Agente IA não seja perdida no roteamento condicional.
 * @param {object} itemAtual - O JSON da iteração atual do loop.
 * @returns {string} A string textual definitiva para exibição.
 */
const cacadorDeTextoPersuasivo = (itemAtual) => {
    // 1. TENTATIVA PRIMÁRIA: Escopo Direto (O nó anterior enviou a string perfeitamente)
    let textoExtraido = itemAtual.output 
        || itemAtual.text 
        || itemAtual.texto_whatsapp_original 
        || itemAtual.resposta_agente 
        || itemAtual.message;

    if (textoExtraido) return sanitizeText(textoExtraido);

    // 2. TENTATIVA SECUNDÁRIA: Busca Explícita no Nó de Decisão (Bypass de Branch Falsa)
    try {
        let nodeDecisao = null;
        if ($('decide texto ou audio') && typeof $('decide texto ou audio').item === 'object') {
            nodeDecisao = $('decide texto ou audio').item.json;
        } else if ($('decide texto ou audio') && typeof $('decide texto ou audio').first === 'function') {
            nodeDecisao = $('decide texto ou audio').first().json;
        }

        if (nodeDecisao) {
            textoExtraido = nodeDecisao.output || nodeDecisao.texto_whatsapp_original || nodeDecisao.text;
            if (textoExtraido) return sanitizeText(textoExtraido);
        }
    } catch (e) {
        console.error("[Inovare Heurística] Falha ao rastrear nó de decisão:", e.message);
    }

    // 3. TENTATIVA TERCIÁRIA: Busca Direta na Raiz do Agente IA
    try {
        let nodeAgente = null;
        if ($('AI Agent') && typeof $('AI Agent').item === 'object') {
            nodeAgente = $('AI Agent').item.json;
        } else if ($('AI Agent') && typeof $('AI Agent').first === 'function') {
            nodeAgente = $('AI Agent').first().json;
        }

        if (nodeAgente) {
            textoExtraido = nodeAgente.output || nodeAgente.text || nodeAgente.response;
            if (textoExtraido) return sanitizeText(textoExtraido);
        }
    } catch (e) {
        console.error("[Inovare Heurística] Falha ao rastrear Agente IA nativo:", e.message);
    }

    // 4. FALLBACK ABSOLUTO: Caso crítico onde a IA realmente falhou em compor a string
    return "Processamento concluído com sucesso.";
};

// ============================================================================
// MOTOR DE EXECUÇÃO PRINCIPAL DO N8N
// ============================================================================

const results = [];

for (let i = 0; i < items.length; i++) {
    try {
        const itemAtual = items[i].json;
        let insightsFiltrados = null;

        // 1. Extração Estruturada e Silenciosa do Contexto da Secretária
        try {
            let jsonSecretariaRaw = null;

            if ($('secretaria') && typeof $('secretaria').item === 'object') {
                jsonSecretariaRaw = $('secretaria').item.json;
            } else if ($('secretária') && typeof $('secretária').item === 'object') {
                jsonSecretariaRaw = $('secretária').item.json;
            } else if ($('secretaria') && typeof $('secretaria').first === 'function') {
                jsonSecretariaRaw = $('secretaria').first().json;
            }

            if (jsonSecretariaRaw) {
                insightsFiltrados = extrairInsightsSecretaria(jsonSecretariaRaw);
            }
        } catch (erroSecretaria) {
            console.error("[Inovare Warning] Falha ao extrair contexto estruturado da secretaria: ", erroSecretaria.message);
            insightsFiltrados = null;
        }

        // 2. Acionamento do Motor Heurístico para Resgate de Texto Bruto
        let textoRespostaGarantido = cacadorDeTextoPersuasivo(itemAtual);

        // 3. Montagem da Estrutura Base do Payload Universal de Saída
        let payloadUniversal = {
            json: {
                output: textoRespostaGarantido,
                possui_midia: false,
                arquivo_base64: null,
                mime_type: null,
                nome_arquivo: null,
                secretaria: insightsFiltrados,
                metadata_processamento: {
                    timestamp: new Date().toISOString(),
                    node_id: "proxy-chat-b2b",
                    status: "payload_universal_construido",
                    ignorado_campos_nulos: true,
                    heuristica_texto_acionada: true
                }
            }
        };

        // 4. Varredura Profunda, Conversão da Camada Binária e EXCLUSÃO MÚTUA
        if (items[i].binary) {
            const chavesBinarias = Object.keys(items[i].binary);

            if (chavesBinarias.length > 0) {
                const chaveAtiva = chavesBinarias[0];
                const dadosBinarios = items[i].binary[chaveAtiva];

                if (dadosBinarios.mimeType) {
                    try {
                        // Consumo via API nativa do n8n para prevenção de Leak de Memória
                        const fileBuffer = await this.helpers.getBinaryDataBuffer(i, chaveAtiva);
                        const base64String = fileBuffer.toString('base64');

                        // Injeção Transacional de Metadados Binários
                        payloadUniversal.json.possui_midia = true;
                        payloadUniversal.json.arquivo_base64 = base64String;
                        payloadUniversal.json.mime_type = dadosBinarios.mimeType;
                        payloadUniversal.json.nome_arquivo = dadosBinarios.fileName || `midia_anexada_inovare_${Date.now()}.${dadosBinarios.fileExtension || 'bin'}`;

                        payloadUniversal.json.metadata_processamento.auditoria_binaria = `Mídia [${dadosBinarios.mimeType}] convertida com sucesso. Length: ${base64String.length}`;

                        // ====================================================================
                        // REGRA DE NEGÓCIO B2B: EXCLUSÃO MÚTUA DE ÁUDIO E TEXTO
                        // ====================================================================
                        // Se o payload contiver um arquivo de áudio (gerado por IA ou encaminhado),
                        // nós esvaziamos a variável 'output' para forçar o Front-End a renderizar
                        // estritamente o player de áudio isolado, sem o texto da transcrição.
                        if (dadosBinarios.mimeType.startsWith('audio/')) {
                            payloadUniversal.json.output = "";
                            payloadUniversal.json.metadata_processamento.exclusao_mutua_aplicada = true;
                            payloadUniversal.json.metadata_processamento.status = "payload_audio_exclusivo";
                        }

                    } catch (binaryError) {
                        payloadUniversal.json.metadata_processamento.auditoria_binaria = `ALERTA: Falha de I/O na extração do buffer binário: ${binaryError.message}`;
                    }
                }
            }
        }

        // Empacotamento do ciclo iterado
        results.push(payloadUniversal);

    } catch (error) {
        // Fallback de Isolamento de Domínio
        results.push({
            json: {
                output: "⚠️ **Alerta de Engenharia:** A requisição foi processada, mas o roteador falhou gravemente na serialização do JSON final.",
                possui_midia: false,
                secretaria: null,
                erro_tecnico: {
                    mensagem: error.message,
                    stack: error.stack,
                    item_index: i,
                    etapa: "engine_payload_universal_proxy"
                }
            }
        });
    }
}

return results;
